initJs:
function(container, apiUrl, tables) {
  const tbody = container.querySelector("#inventory-tbody");
  const errorMessage = container.querySelector("#error-message");
  const noResultsMessage = container.querySelector("#no-results-message");
  const storeSelect = container.querySelector("#store-select");

  // 店舗マスタのデータを店舗選択に設定
  const storeTable = tables.find(t => t.tableName === "店舗マスタ");
  if (storeTable && storeTable.records) {
    storeTable.records.forEach(store => {
      if (store.有効フラグ) {
        const option = document.createElement("option");
        option.value = store.店舗ID;
        option.textContent = `${store.店舗コード} - ${store.店舗名}`;
        storeSelect.appendChild(option);
      }
    });
  }

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove("hidden");
    setTimeout(() => {
      errorMessage.classList.add("hidden");
    }, 5000);
  }

  // 在庫状況判定関数
  function getStockStatus(currentStock, safetyStock) {
    if (currentStock <= 0) return "不足";
    if (currentStock <= safetyStock) return "不足";
    if (currentStock > safetyStock * 2) return "過剰";
    return "適正";
  }

  // 在庫状況の色分け
  function getStatusColor(status) {
    switch (status) {
      case "不足": return "color: #ff6b6b;";
      case "過剰": return "color: #ffa726;";
      case "適正": return "color: #4caf50;";
      default: return "color: var(--text);";
    }
  }

  // テーブル再描画関数
  function renderRows(inventoryData) {
    if (!inventoryData || inventoryData.length === 0) {
      tbody.innerHTML = "";
      noResultsMessage.classList.remove("hidden");
      return;
    }

    noResultsMessage.classList.add("hidden");
    tbody.innerHTML = inventoryData.map(item => {
      const status = getStockStatus(item.現在在庫数 || 0, item.安全在庫数 || 0);
      const statusStyle = getStatusColor(status);
      const updateTime = item.更新日時 ? new Date(item.更新日時).toLocaleString() : "";

      return `
        <tr data-id="${item.商品ID || ''}">
          <td>${item.商品コード || ""}</td>
          <td>${item.商品名 || ""}</td>
          <td style="${item.現在在庫数 === 0 ? 'color: #ff6b6b; font-weight: bold;' : ''}">${item.現在在庫数 || 0}</td>
          <td>${item.安全在庫数 || 0}</td>
          <td style="${statusStyle}">${status}</td>
          <td class="muted">${updateTime}</td>
        </tr>
      `;
    }).join("");
  }

  // 検索処理
  async function performSearch() {
    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-filter").value;
    const productName = container.querySelector("#product-name-search").value.trim();
    const productCode = container.querySelector("#product-code-search").value.trim();
    const stockStatus = container.querySelector("#stock-status-filter").value;

    // バリデーション
    if (!storeId) {
      showError("店舗を選択してください");
      return;
    }

    // 商品名の特殊文字チェック
    if (productName && /<script|javascript:|on\w+\s*=|'|"|;|DROP|SELECT|INSERT|UPDATE|DELETE/i.test(productName)) {
      showError("商品名に無効な文字が含まれています");
      return;
    }

    // 商品コードの数値チェック（入力がある場合のみ）
    if (productCode && !/^\d+$/.test(productCode)) {
      showError("商品コードは数値で入力してください");
      return;
    }

    try {
      // 商品マスタを取得
      const productTable = tables.find(t => t.tableName === "商品マスタ");
      let products = productTable ? productTable.records || [] : [];

      // 在庫データを模擬生成（実際の実装では在庫テーブルから取得）
      let inventoryData = products.filter(p => p.有効フラグ).map(product => ({
        商品ID: product.商品ID,
        商品コード: product.商品コード,
        商品名: product.商品名,
        商品カテゴリ: product.商品カテゴリID === "cat1" ? "食品" : 
                     product.商品カテゴリID === "cat2" ? "日用品" : 
                     product.商品カテゴリID === "cat3" ? "衣料品" : "家電",
        現在在庫数: Math.floor(Math.random() * 200),
        安全在庫数: Math.floor(Math.random() * 50) + 10,
        更新日時: new Date().toISOString()
      }));

      // フィルタリング
      if (category) {
        inventoryData = inventoryData.filter(item => item.商品カテゴリ === category);
      }

      if (productName) {
        inventoryData = inventoryData.filter(item => 
          item.商品名 && item.商品名.toLowerCase().includes(productName.toLowerCase())
        );
      }

      if (productCode) {
        inventoryData = inventoryData.filter(item => 
          item.商品コード && item.商品コード.includes(productCode)
        );
      }

      if (stockStatus) {
        inventoryData = inventoryData.filter(item => {
          const status = getStockStatus(item.現在在庫数, item.安全在庫数);
          return status === stockStatus;
        });
      }

      renderRows(inventoryData);

    } catch (error) {
      console.error("検索エラー:", error);
      showError("検索中にエラーが発生しました");
    }
  }

  // 検索条件クリア
  function clearSearchConditions() {
    container.querySelector("#store-select").value = "";
    container.querySelector("#category-filter").value = "";
    container.querySelector("#product-name-search").value = "";
    container.querySelector("#product-code-search").value = "";
    container.querySelector("#stock-status-filter").value = "";
    tbody.innerHTML = "";
    noResultsMessage.classList.add("hidden");
  }

  // CSVエクスポート
  function exportToCSV() {
    const rows = Array.from(tbody.querySelectorAll("tr"));
    if (rows.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    const headers = ["商品コード", "商品名", "現在在庫数", "安全在庫数", "在庫状況", "最終更新日時"];
    const csvData = [headers.join(",")];

    rows.forEach(row => {
      const cells = Array.from(row.querySelectorAll("td"));
      const rowData = cells.map(cell => {
        const text = cell.textContent.trim();
        return text.includes(",") ? `"${text}"` : text;
      });
      csvData.push(rowData.join(","));
    });

    const csvContent = "\uFEFF" + csvData.join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `在庫一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // イベントリスナー
  container.querySelector("#btn-search").addEventListener("click", performSearch);
  container.querySelector("#btn-clear").addEventListener("click", clearSearchConditions);
  container.querySelector("#btn-export").addEventListener("click", exportToCSV);

  // Enterキーで検索
  container.querySelector("#product-name-search").addEventListener("keypress", (e) => {
    if (e.key === "Enter") performSearch();
  });

  container.querySelector("#product-code-search").addEventListener("keypress", (e) => {
    if (e.key === "Enter") performSearch();
  });

  // 初期表示（空のテーブル）
  renderRows([]);
}
